/**
 * Test flow for copyAttachment action
 * Demonstrates copying an attachment from one record to another
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testCopyAttachment = Flow(
    {
        $id: Now.ID['test_copy_attachment_flow'],
        name: 'Test Copy Attachment',
        description: 'Tests the copyAttachment core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_copy_attachment_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        // Create a target incident
        const targetIncident = wfa.action(
            action.core.createRecord,
            { $id: Now.ID['test_copy_attachment_create_target'] },
            {
                table_name: 'incident',
                values: TemplateValue({
                    short_description: 'Target Incident',
                    priority: 3,
                }),
            }
        )

        wfa.action(
            action.core.copyAttachment,
            { $id: Now.ID['test_copy_attachment_action'] },
            {
                table: 'incident',
                target_record: wfa.dataPill(targetIncident.record, 'reference'),
                attachment_record: 'sample_attachment_sys_id',
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_copy_attachment_log'] },
            {
                log_level: 'info',
                log_message: `copyAttachment outputs: target_record=${wfa.dataPill(targetIncident.record, 'reference')}`,
            }
        )
    }
)
